SELECT cdscode
FROM frpm
WHERE (COALESCE("Enrollment (K-12)", 0) + COALESCE("Enrollment (Ages 5-17)", 0)) > 500;

SELECT COUNT(*) AS num_districts
FROM district
WHERE a11 > 6000 AND a11 < 10000;

SELECT CAST(SUM(CASE WHEN status = 'C' THEN amount ELSE 0 END) AS REAL) * 100 / SUM(amount) AS pct_running_ok
FROM loan
WHERE amount < 100000;

SELECT COUNT(*) AS circuit_count
FROM circuits
WHERE location = 'Adelaide' AND country = 'Australia';

SELECT player_name
FROM player
WHERE substr(birthday,1,7) = '1970-10';

WITH pat AS (
  SELECT id FROM patient WHERE birthday = '1959-02-18'
),
nov AS (
  SELECT SUM(l."T-CHO") AS s FROM laboratory l JOIN pat p ON l.id = p.id
  WHERE l.date >= '1981-11-01' AND l.date < '1981-12-01'
),
dec AS (
  SELECT SUM(l."T-CHO") AS s FROM laboratory l JOIN pat p ON l.id = p.id
  WHERE l.date >= '1981-12-01' AND l.date < '1982-01-01'
)
SELECT CAST((nov.s - dec.s) AS REAL) * 100 / dec.s AS decrease_rate_pct
FROM nov, dec;
